H.background();
const k = P.k, A = P.A;
const x = A * Math.sin(t * 1.4);
const Fspring = -k * x;
const PE = 0.5 * k * x * x;
const w = H.W, hh = H.H;
const wallX = w * 0.12, yMid = hh * 0.5;
const eqX = w * 0.5;
const pxPerM = (w * 0.32) / Math.max(0.1, A);
const bx = eqX + x * pxPerM;
H.rect(wallX - 14, yMid - 60, 14, 120, { fill: H.colors.panel, stroke: H.colors.axis, width: 2 });
const coils = 14, sx = wallX, ex = bx - 26;
const pts = [];
for (let i = 0; i <= coils; i++) {
  const f = i / coils;
  const xx = sx + (ex - sx) * f;
  const yy = yMid + (i === 0 || i === coils ? 0 : (i % 2 ? -14 : 14));
  pts.push([xx, yy]);
}
H.path(pts, { color: H.colors.accent, width: 2.5 });
H.rect(bx - 26, yMid - 22, 52, 44, { fill: H.colors.panel, stroke: H.colors.accent2, width: 2, radius: 5 });
H.line(eqX, yMid - 70, eqX, yMid + 70, { color: H.colors.grid, width: 1.5, dash: [4, 4] });
H.text("x = 0", eqX - 14, yMid + 88, { color: H.colors.sub, size: 12 });
const aL = 6 + Math.abs(Fspring) * 6;
const dir = Fspring >= 0 ? 1 : -1;
H.arrow(bx, yMid, bx + dir * aL, yMid, { color: H.colors.warn, width: 4, head: 11 });
H.text("F = -kx", bx + dir * aL + dir * 6, yMid - 8, { color: H.colors.warn, size: 12, align: dir > 0 ? "left" : "right" });
H.text("Spring PE (Hooke's law):  PE = ½ k x²", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("k = " + k.toFixed(0) + " N/m    x = " + x.toFixed(2) + " m    F = " + Fspring.toFixed(1) + " N    PE = " + PE.toFixed(2) + " J", 24, 54, { color: H.colors.sub, size: 13 });
